package capstone.coverstory.application;
import org.junit.jupiter.api.Tag;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@Tag("learnerAcceptance") class CAP100AcceptanceTest {
 private final QuarantineInvalidOnboardingEvidenceRows seam=new QuarantineInvalidOnboardingEvidenceRows();
 private static QuarantineInvalidOnboardingEvidenceRows.AuditRow r(String o,String id,Object n,String pin,boolean confirmed,int rev){return new QuarantineInvalidOnboardingEvidenceRows.AuditRow(o,id,n,rev,pin,confirmed);}
 @Test void sixRowCounts(){var rows=List.of(r("customer-A","x1",1,"411001",false,12),r("customer-A","x2",2,null,false,12),r("customer-A","x3",3,null,false,12),r("customer-A","x1",1,null,false,12),r("customer-A",null,1,null,false,12),r("customer-A","x4",true,null,false,12));var out=seam.validateEvidenceBatch(new QuarantineInvalidOnboardingEvidenceRows.Batch("customer-A",12,Set.of()),rows);assertEquals(new QuarantineInvalidOnboardingEvidenceRows.Counts(3,1,1,1,6),out.counts());}
 @Test void ownerPartitionUsesTrustedOwnerAndRowId(){var a=seam.validateEvidenceBatch(new QuarantineInvalidOnboardingEvidenceRows.Batch("customer-A",12,Set.of()),List.of(r("customer-A","x",1,null,false,12)));var b=seam.validateEvidenceBatch(new QuarantineInvalidOnboardingEvidenceRows.Batch("customer-B",12,Set.of()),List.of(r("customer-B","x",1,null,false,12)));assertNotEquals(a.acceptedIds().get(0),b.acceptedIds().get(0));assertFalse(a.acceptedIds().contains(new QuarantineInvalidOnboardingEvidenceRows.RowKey("customer-B","x")));}
 @Test void replayCountsDuplicatesWithoutAddingUniqueRows(){var key=new QuarantineInvalidOnboardingEvidenceRows.RowKey("customer-A","x");var out=seam.validateEvidenceBatch(new QuarantineInvalidOnboardingEvidenceRows.Batch("customer-A",12,Set.of(key)),List.of(r("customer-A","x",1,null,false,12)));assertEquals(0,out.counts().accepted());assertEquals(1,out.counts().duplicate());}
 @Test void proposalDoesNotChangeConfirmationOrRatingRevision(){var out=seam.validateEvidenceBatch(new QuarantineInvalidOnboardingEvidenceRows.Batch("customer-A",12,Set.of()),List.of(r("customer-A","pin",1,"411001",false,12)));assertEquals(12,out.ratingRevision());assertFalse(out.disclosureConfirmed());}
 @Test void booleanZeroAndNullAreInvalidAttempts(){for(Object n:Arrays.asList(true,0,null)){var out=seam.validateEvidenceBatch(new QuarantineInvalidOnboardingEvidenceRows.Batch("customer-A",12,Set.of()),List.of(r("customer-A","fresh",n,null,false,12)));assertEquals(1,out.counts().invalidAttempt());}}
}
